from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    trans: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_to_idx[ch]
            nxt = trans[node][c]
            if nxt == -1:
                nxt = len(trans)
                trans[node][c] = nxt
                trans.append([-1] * k)
                bad.append(False)
            node = nxt
        bad[node] = True

    num_states = len(trans)
    fail = [0] * num_states
    q: deque[int] = deque()

    for c in range(k):
        nxt = trans[0][c]
        if nxt != -1:
            fail[nxt] = 0
            q.append(nxt)
        else:
            trans[0][c] = 0

    while q:
        u = q.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = trans[u][c]
            if v != -1:
                fail[v] = trans[fail[u]][c]
                q.append(v)
            else:
                trans[u][c] = trans[fail[u]][c]

    good_states = [i for i in range(num_states) if not bad[i]]
    if not good_states:
        return 0

    m = len(good_states)
    state_to_idx = {s: i for i, s in enumerate(good_states)}
    mat = [[0] * m for _ in range(m)]
    for i, u in enumerate(good_states):
        for c in range(k):
            v = trans[u][c]
            if not bad[v]:
                mat[i][state_to_idx[v]] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            row_a = a[i]
            row_res = res[i]
            for j in range(m):
                aj = row_a[j]
                if aj:
                    row_b = b[j]
                    for col in range(m):
                        row_res[col] += aj * row_b[col]
            for col in range(m):
                row_res[col] %= MOD
        return res

    vec = [0] * m
    vec[0] = 1
    base = mat
    exp = n
    while exp > 0:
        if exp & 1:
            nxt_vec = [0] * m
            for i in range(m):
                vi = vec[i]
                if vi:
                    row_b = base[i]
                    for j in range(m):
                        nxt_vec[j] += vi * row_b[j]
            vec = [x % MOD for x in nxt_vec]
        exp >>= 1
        if exp > 0:
            base = mat_mul(base, base)

    return sum(vec) % MOD
